from lib import *
S = SS('p41')
steps = [
    step("基准:初始 1000 条数据、每页 20 条、约 50 页,页与页之间客户端间隔 10 ms;“漏掉”=初始就有、整个抓取期间都没被删除、却从没返回过的条数;“重复”=返回的总条数减去不同的条数。数据没有变化时,四种分页方式(偏移量最新在前、偏移量最旧在前、游标最新在前、服务器快照)都是 51 次请求、1000 条、0 重复、0 漏掉。", t=tl(S(1)), done=lidx(S(1), '偏移量分页,最新在前', '服务器快照分页'), b=bars([['重复', 0, '0'], ['漏掉', 0, '0'], ['返回条数', 1000, '1000']], 1000, done=[0, 1, 2]), kv=KV([['四种分页', '都是 1000 条'], ['重复', '0'], ['漏掉', '0']], ['四种分页'])),
    step("抓取期间不断新增数据(每 4 ms 新增一条,新增的是最新的,抓取期间新增约 151 条)。偏移量分页、最新在前:59 页,返回 1148 条,其中重复 148(3 次运行 149、148、147),漏掉 0——新数据插在最前面,把后面的条目整体往后推,下一页又读到上一页读过的条目。偏移量分页、最旧在前:没有重复、没有漏掉,还顺便读到了抓取期间新增的数据(返回 1142 条,新数据在末尾)。游标分页:1000 条,0 重复 0 漏掉(不返回抓取开始之后新增的);快照分页:1000 条,0 重复 0 漏掉。", t=tl(S(2)), done=lidx(S(2), '偏移量分页,最旧在前', '游标', '快照'), mark=lidx(S(2), '偏移量分页,最新在前'), b=bars([['偏移量·最新在前:重复', 148, '148'], ['偏移量·最旧在前:重复', 0, '0'], ['游标:重复', 0, '0'], ['快照:重复', 0, '0']], 160, mark=[0], done=[1, 2, 3]), kv=KV([['偏移量 + 最新在前', '重复 148 条'], ['偏移量 + 最旧在前', '无重复,还多读到新数据'], ['游标 / 快照', '无重复无漏掉']], ['偏移量 + 最新在前'])),
    step("抓取期间不断随机删除数据(每 4 ms 删一条,期间删除约 120 条)。偏移量分页最新在前:返回 884 条,漏掉 59 条(3 次 58、59、60);偏移量分页最旧在前:889 条,漏掉 46 条(54、46、52)——前面有条目被删除,后面的整体前移,下一页的偏移量就跳过了几条。游标分页:947 条,0 漏掉(被删除的条目自然没返回,存活的都读到了);快照分页:1000 条,0 漏掉(包括抓取期间已经被删掉的条目,是旧快照里的)。", t=tl(S(3)), done=lidx(S(3), '游标', '快照'), mark=lidx(S(3), '偏移量分页'), b=bars([['偏移量·最新在前:漏掉', 59, '59'], ['偏移量·最旧在前:漏掉', 46, '46'], ['游标:漏掉', 0, '0'], ['快照:漏掉', 0, '0']], 65, mark=[0, 1], done=[2, 3]), kv=KV([['偏移量(任一排序)', '漏掉 46–59 条'], ['游标', '0 漏掉,不含已删除的'], ['快照', '0 漏掉,含已删除的旧数据']], ['偏移量(任一排序)'])),
    step("同时新增和删除(各约 138 条):偏移量最新在前 返回 1000 条里重复 60、漏掉 0(新增的“推后”和删除的“拉前”大致抵消,仍然有重复);偏移量最旧在前 漏掉 45;游标 0 重复 0 漏掉(返回 950);快照 0 重复 0 漏掉(1000)。只有游标和快照在三种变化下都既不重复也不漏掉。", t=tl(S(4)), done=lidx(S(4), '游标', '快照'), mark=lidx(S(4), '偏移量分页'), kv=KV([['偏移量 最新在前', '重复 60'], ['偏移量 最旧在前', '漏掉 45'], ['游标 / 快照', '重复 0,漏掉 0']], ['游标 / 快照'])),
    step("确定性的小演示(100 条数据 id 1..100、每页 5 条,不用线程):读完第 2 页(最新在前是 95 到 91)之后数据变化,再读第 3 页。新增 3 条(101–103):偏移量最新在前的第 3 页变成 [93, 92, 91, 90, 89],93、92、91 是第 2 页已经读过的——重复;偏移量最旧在前仍是 [11…15];游标是 [90…86],正是下一页应有的内容。删除 3 条已读过的条目(100、99、98):偏移量最新在前的第 3 页变成 [87…83],本该读到的 90、89、88 被跳过了——漏掉;游标仍是 [90…86];偏移量最旧在前不受影响(删的是另一端)。偏移量分页的“第 N 页”是按当前数据排出来的位置,数据在抓取过程中移动,位置就失效。", t=tl(S(5)), done=lidx(S(5), 'cursor'), mark=lidx(S(5), 'offset_new'), kv=KV([['新增 3 条后 offset_new 的第 3 页', '[93…89],重复了 93、92、91'], ['删除 3 条后 offset_new 的第 3 页', '[87…83],漏了 90、89、88'], ['游标', '两种变化下都是 [90…86]']], ['游标'])),
]
A = mkartp('p41', 41, '爬虫,分页,偏移量分页,游标分页,快照,漏抓,重复,Python,真实验证,动画演示',
    '在抓取过程中让数据不断新增和删除:偏移量分页(最新在前)返回 1148 条中重复 148 条,随机删除时漏掉 59 条;最旧在前仍然漏掉 46 条;游标分页和快照分页在新增、删除、新增加删除三种变化下都没有重复也没有漏掉。',
    '抓一个分页列表时,数据可能正在变化。用 offset 翻页,新数据一插入,下一页就读到上一页读过的条目;删了前面的条目,后面的又被跳过。这篇用一个会同时新增和删除数据的本机服务器,对比四种分页方式的重复和漏抓。',
    [('148 条', '新增数据时偏移量分页(最新在前)的重复条数——游标和快照是 0'), ('59 条', '随机删除数据时偏移量分页(最新在前)漏掉的条数——游标和快照是 0'), ('0 / 0', '游标分页在新增、删除、两者并存时的 重复 / 漏掉')],
    [('基准', '<p>数据不变时四种方式没有区别,都是 51 次请求、1000 条。</p>'),
     ('新增数据 → 重复', '<p>最新在前的偏移量分页:新数据插在最前面,把已读过的条目向后推到后面的页里,于是下一页又读一遍,重复 148 条。最旧在前时新数据追加在末尾,没有重复、也没有漏,抓取还读到了新增的数据。</p>'),
     ('删除数据 → 漏掉', '<p>偏移量分页不论排序,前面有条目被删除,后面的条目前移一格,下一页的偏移量就跳过它们:漏掉 46 到 59 条。游标分页以最后一条 id 继续,不受影响;快照分页返回冻结时的数据(包括之后被删除的条目)。</p>'),
     ('新增加删除', '<p>两种变化同时发生时,偏移量分页的结果更难预料(重复 60 或漏掉 45,取决于排序);游标和快照仍然既不重复也不漏掉。</p>'),
     ('怎么选', '<p>能用游标(按 id 或时间戳继续)就用游标;API 只给 offset 时,最旧在前加倍抓取校验(用抓到的 id 去重,并在结束后再扫一遍)可以减少风险。本实验没有测校验方案。</p>')],
    steps,
    [ENV_P + '。本机服务器保存一个 id 列表,另一个线程每 4 ms 新增(追加递增的 id)或随机删除一条;四种接口:offset_new(按 id 倒序切片)、offset_old(按 id 升序切片)、cursor(id 小于 before 的 20 条)、snapshot(第一次请求时冻结整份数据);客户端每页间隔 10 ms;“漏掉”以初始 1000 条中整个抓取期间都没被删除的为准;每种情形跑 3 次,主要数字取第 2 次,3 次的结果写在括号里',
     '没有验证:真实 API 的分页(例如返回 next_cursor 的 API 里游标含义不同);数据变更频率更高或更低时的比例;用重复检查和二次扫描来弥补偏移量分页的做法;分页大小对结果的影响;更新(修改排序字段)而不是插入或删除的情形;并发多页同时抓取时的一致性'],
    '分页抓取的漂移')
